try:
    print('>>> f = divmod')
    print('>>> x = range(0)')
    print('>>> y = bytearray()')
    print('>>> f(x, y)')
    f = divmod
    x = range(0)
    y = bytearray()
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
